/**
 * Script to generate coverage badge
 * Reads coverage summary and generates a badge SVG file
 */

import { readFileSync, writeFileSync, existsSync } from 'fs';
import { join } from 'path';

const coverageSummaryPath = join(process.cwd(), 'coverage', 'coverage-summary.json');
const coverageFinalPath = join(process.cwd(), 'coverage', 'coverage-final.json');
const badgeOutputPath = join(process.cwd(), 'coverage', 'coverage-badge.svg');

let coveragePercent = 0;

try {
    // Try coverage-summary.json first (generated by vitest coverage)
    let coverageData = null;
    if (existsSync(coverageSummaryPath)) {
        coverageData = JSON.parse(readFileSync(coverageSummaryPath, 'utf-8'));
        if (coverageData.total && coverageData.total.statements) {
            coveragePercent = Math.round(coverageData.total.statements.pct || 0);
        }
    } else if (existsSync(coverageFinalPath)) {
        // Fallback to coverage-final.json
        const coverage = JSON.parse(readFileSync(coverageFinalPath, 'utf-8'));
        
        // Calculate from individual files
        let totalStatements = 0;
        let coveredStatements = 0;
        
        for (const filePath in coverage) {
            if (filePath === 'total') {
                // If total exists, use it
                if (coverage.total && coverage.total.statements) {
                    coveragePercent = Math.round(coverage.total.statements.pct || 0);
                    break;
                }
                continue;
            }
            const file = coverage[filePath];
            if (file && file.s) {
                const statements = Object.keys(file.s);
                totalStatements += statements.length;
                coveredStatements += statements.filter(key => file.s[key] > 0).length;
            }
        }
        
        if (coveragePercent === 0 && totalStatements > 0) {
            coveragePercent = Math.round((coveredStatements / totalStatements) * 100);
        }
    } else {
        throw new Error('Coverage file not found');
    }
} catch (error) {
    console.error('Error generating coverage badge:', error.message);
    coveragePercent = 0; // Default to 0 if error
}

// Determine badge color based on coverage
let color = 'e05d44'; // red
if (coveragePercent >= 80) color = '97ca00'; // green
else if (coveragePercent >= 70) color = 'a4a61d'; // yellowgreen
else if (coveragePercent >= 60) color = 'dfb317'; // yellow
else if (coveragePercent >= 40) color = 'fe7d37'; // orange

// Generate SVG badge
const badgeSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="99" height="20">
  <linearGradient id="b" x2="0" y2="100%">
    <stop offset="0" stop-color="#bbb" stop-opacity=".1"/>
    <stop offset="1" stop-opacity=".1"/>
  </linearGradient>
  <mask id="a">
    <rect width="99" height="20" rx="3" fill="#fff"/>
  </mask>
  <g mask="url(#a)">
    <path fill="#555" d="M0 0h63v20H0z"/>
    <path fill="#${color}" d="M63 0h36v20H63z"/>
    <path fill="url(#b)" d="M0 0h99v20H0z"/>
  </g>
  <g fill="#fff" text-anchor="middle" font-family="DejaVu Sans,Verdana,Geneva,sans-serif" font-size="11">
    <text x="31.5" y="15" fill="#010101" fill-opacity=".3">coverage</text>
    <text x="31.5" y="14">coverage</text>
    <text x="81" y="15" fill="#010101" fill-opacity=".3">${coveragePercent}%</text>
    <text x="81" y="14">${coveragePercent}%</text>
  </g>
</svg>`;

// Write badge to file
writeFileSync(badgeOutputPath, badgeSvg, 'utf-8');

console.log(`Coverage: ${coveragePercent}%`);
console.log(`Badge generated: ${badgeOutputPath}`);
